sp_EditarCliente	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_EditarCliente`(\n\n    IN p_idCliente      INT,\n\n    IN p_nome           VARCHAR(150),\n\n    IN p_nomeFantasia   VARCHAR(150),\n\n    IN p_razaoSocial    VARCHAR(150),\n\n    IN p_cpfCNPJ        VARCHAR(18),\n\n    IN p_email          VARCHAR(255),\n\n    IN p_telefone       VARCHAR(20),\n\n    IN p_tipoCliente_id INT,\n\n    IN p_observacao     VARCHAR(500),\n\n    IN p_genero         CHAR(1),\n\n    IN p_enderecoId     INT,\n\n    IN p_dthNascimento  DATETIME,\n\n    IN p_saldoDevedor   DECIMAL(20, 2)\n\n)\nBEGIN\n\n    UPDATE Cliente SET\n\n        Nome           = COALESCE(p_nome,           Nome),\n\n        nomeFantasia   = COALESCE(p_nomeFantasia,   nomeFantasia),\n\n        razaoSocial    = COALESCE(p_razaoSocial,    razaoSocial),\n\n        CNPJ_CPF       = COALESCE(p_cpfCNPJ,        CNPJ_CPF),\n\n        Email          = COALESCE(p_email,           Email),\n\n        Telefone       = COALESCE(p_telefone,        Telefone),\n\n        tipoCliente_id = COALESCE(p_tipoCliente_id, tipoCliente_id),\n\n        Observacao     = COALESCE(p_observacao,      Observacao),\n\n        Genero         = COALESCE(p_genero,          Genero),\n\n        enderecoId     = COALESCE(p_enderecoId,      enderecoId),\n\n        dthNascimento  = COALESCE(p_dthNascimento,   dthNascimento),\n\n        saldoDevedor   = COALESCE(p_saldoDevedor,    saldoDevedor)\n\n    WHERE idCliente = p_idCliente;\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
